// Pure-JS HMAC-SHA256 (works inside n8n v2 JS Task Runner without requiring Node 'crypto' module)
function utf8Bytes(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.charCodeAt(i);
    if (code < 0x80) bytes.push(code);
    else if (code < 0x800) bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    else if (code < 0xd800 || code >= 0xe000) bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    else {
      i++;
      code = 0x10000 + (((code & 0x3ff) << 10) | (str.charCodeAt(i) & 0x3ff));
      bytes.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    }
  }
  return new Uint8Array(bytes);
}

function sha256(msgBytes) {
  const K = new Uint32Array([
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ]);
  const H = new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);
  const l = msgBytes.length;
  const bitLen = l * 8;
  const padLen = ((l + 9 + 63) >> 6) << 6;
  const padded = new Uint8Array(padLen);
  padded.set(msgBytes);
  padded[l] = 0x80;
  const dv = new DataView(padded.buffer);
  dv.setUint32(padLen - 8, Math.floor(bitLen / 0x100000000), false);
  dv.setUint32(padLen - 4, bitLen >>> 0, false);
  const W = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padLen; off += 64) {
    for (let i = 0; i < 16; i++) W[i] = dv.getUint32(off + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(W[i-15],7) ^ rotr(W[i-15],18) ^ (W[i-15]>>>3);
      const s1 = rotr(W[i-2],17) ^ rotr(W[i-2],19) ^ (W[i-2]>>>10);
      W[i] = (W[i-16] + s0 + W[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ ((~e) & g);
      const t1 = (h + S1 + ch + K[i] + W[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  const out = new Uint8Array(32);
  const odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i], false);
  return out;
}

function hmacSha256Base64(secretStr, msgBytes) {
  let key = utf8Bytes(secretStr);
  if (key.length > 64) key = sha256(key);
  const ipad = new Uint8Array(64);
  const opad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) {
    const k = i < key.length ? key[i] : 0;
    ipad[i] = k ^ 0x36;
    opad[i] = k ^ 0x5c;
  }
  const inner = new Uint8Array(64 + msgBytes.length);
  inner.set(ipad);
  inner.set(msgBytes, 64);
  const innerHash = sha256(inner);
  const outer = new Uint8Array(64 + 32);
  outer.set(opad);
  outer.set(innerHash, 64);
  const mac = sha256(outer);
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let b64 = '';
  for (let i = 0; i < mac.length; i += 3) {
    const b0 = mac[i], b1 = i + 1 < mac.length ? mac[i + 1] : 0, b2 = i + 2 < mac.length ? mac[i + 2] : 0;
    const trip = (b0 << 16) | (b1 << 8) | b2;
    b64 += chars[(trip >> 18) & 63] + chars[(trip >> 12) & 63] + (i + 1 < mac.length ? chars[(trip >> 6) & 63] : '=') + (i + 2 < mac.length ? chars[trip & 63] : '=');
  }
  return b64;
}

function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const item = $input.first();
const payload = item.json || {};
const headers = payload.headers || {};
const order = (payload.body && typeof payload.body === 'object') ? payload.body : payload;

// Read centralized settings
const threshold = Number(payload.low_stock_threshold ?? 5);
const storeDomain = payload.shopify_store_domain || 'northern-treasures-a73kt59n.myshopify.com';
const apiVersion = payload.shopify_api_version || '2026-10';
const storeName = payload.store_name || 'Northern Treasures';
const ownerChatId = String(payload.owner_telegram_chat_id || '');
const webhookSecret = String(payload.shopify_webhook_secret || '');
const enforceHmac = payload.enforce_hmac !== false;
const sheetId = String(payload.google_sheet_id || '');
const sheetTab = String(payload.google_sheet_tab || 'Orders');
const senderEmail = String(payload.sender_email || '');

// 1. Verify Shopify HMAC-SHA256 signature
let hmacStatus = 'verified';
let hmacValid = true;
const secretConfigured = Boolean(webhookSecret && !webhookSecret.startsWith('REPLACE_WITH_'));

if (enforceHmac && secretConfigured) {
  let receivedHmac = '';
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === 'x-shopify-hmac-sha256') {
      receivedHmac = Array.isArray(v) ? v[0] : String(v || '');
      break;
    }
  }
  if (!receivedHmac) {
    hmacValid = false;
    hmacStatus = 'missing_header';
  } else {
    let rawBuf = null;
    try {
      if (item.binary && item.binary.data) {
        if (typeof this !== 'undefined' && this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
          rawBuf = new Uint8Array(await this.helpers.getBinaryDataBuffer(0, 'data'));
        } else if (item.binary.data.data) {
          rawBuf = new Uint8Array(Buffer.from(item.binary.data.data, 'base64'));
        }
      }
    } catch (e) {
      rawBuf = null;
    }
    if (!rawBuf) {
      rawBuf = utf8Bytes(JSON.stringify(order));
    }
    const computed = hmacSha256Base64(webhookSecret, rawBuf);
    if (!safeEqual(computed, receivedHmac.trim())) {
      hmacValid = false;
      hmacStatus = 'mismatch';
    }
  }
} else if (!secretConfigured) {
  hmacStatus = 'secret_not_configured';
}

if (!hmacValid) {
  return [{
    json: {
      route: 'invalid',
      errorReason: 'Shopify HMAC verification failed (' + hmacStatus + '). Request rejected.',
      orderId: String(order.name || order.id || 'Unknown'),
      owner_telegram_chat_id: ownerChatId,
      hmacStatus,
    },
  }];
}

// 2. Extract and validate required order fields
const shopifyOrderId = order.id !== undefined && order.id !== null ? String(order.id).trim() : '';
const orderId = String(order.name || (order.order_number ? '#' + order.order_number : '') || shopifyOrderId).trim();

const cust = order.customer || {};
const bill = order.billing_address || {};
const ship = order.shipping_address || {};
const fullName = [cust.first_name, cust.last_name].filter(Boolean).join(' ').trim()
  || bill.name
  || ship.name
  || 'Valued Customer';
const customerEmail = String(order.email || order.contact_email || cust.email || '').trim();
const hasValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail);
const currency = String(order.currency || order.presentment_currency || 'PKR');
const totalAmount = Number(order.total_price ?? order.current_total_price ?? 0);

const rawItems = Array.isArray(order.line_items) ? order.line_items : [];
if (!shopifyOrderId || !orderId || rawItems.length === 0) {
  return [{
    json: {
      route: 'invalid',
      errorReason: 'Malformed order payload: missing Order ID or line_items.',
      orderId: orderId || 'Missing',
      owner_telegram_chat_id: ownerChatId,
      hmacStatus,
    },
  }];
}

const lineItems = rawItems.map((li, idx) => {
  const qty = Number(li.quantity);
  const price = Number(li.price ?? 0);
  const lineRevenue = Number((price * qty).toFixed(2));
  return {
    itemIndex: idx + 1,
    totalItems: rawItems.length,
    lineItemId: String(li.id || idx + 1),
    productId: li.product_id ? String(li.product_id) : '',
    variantId: li.variant_id ? String(li.variant_id) : '',
    productTitle: String(li.title || li.name || 'Unnamed Product'),
    variantTitle: String(li.variant_title || ''),
    sku: String(li.sku || 'N/A'),
    quantity: qty,
    unitPrice: price,
    lineRevenue,
  };
});

const badQty = lineItems.find((x) => !Number.isFinite(x.quantity) || x.quantity <= 0);
if (badQty) {
  return [{
    json: {
      route: 'invalid',
      errorReason: 'Invalid quantity (' + badQty.quantity + ') for item "' + badQty.productTitle + '" in order ' + orderId,
      orderId,
      owner_telegram_chat_id: ownerChatId,
      hmacStatus,
    },
  }];
}

// 3. Duplicate webhook / idempotency protection
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedOrders || typeof staticData.processedOrders !== 'object') {
  staticData.processedOrders = {};
}

if (staticData.processedOrders[shopifyOrderId]) {
  return [{
    json: {
      route: 'duplicate',
      errorReason: 'Duplicate webhook detected for Order ' + orderId + ' (ID: ' + shopifyOrderId + '). Previously processed at ' + staticData.processedOrders[shopifyOrderId] + '. Inventory was NOT reduced again.',
      orderId,
      shopifyOrderId,
      owner_telegram_chat_id: ownerChatId,
      hmacStatus,
    },
  }];
}

const processedAt = new Date().toLocaleString('en-PK', { timeZone: 'Asia/Karachi', hour12: true });
const processedIso = new Date().toISOString();
staticData.processedOrders[shopifyOrderId] = processedIso;

// Keep staticData bounded to last 500 orders
const keys = Object.keys(staticData.processedOrders);
if (keys.length > 500) {
  for (const oldKey of keys.slice(0, keys.length - 500)) {
    delete staticData.processedOrders[oldKey];
  }
}

return [{
  json: {
    route: 'valid',
    hmacStatus,
    orderId,
    shopifyOrderId,
    customerName: fullName,
    customerEmail,
    hasValidEmail,
    customerDisplay: hasValidEmail ? (fullName + ' (' + customerEmail + ')') : (fullName + ' (No Email Provided)'),
    currency,
    totalAmount,
    processedAt,
    processedIso,
    low_stock_threshold: threshold,
    shopify_store_domain: storeDomain,
    shopify_api_version: apiVersion,
    store_name: storeName,
    owner_telegram_chat_id: ownerChatId,
    google_sheet_id: sheetId,
    google_sheet_tab: sheetTab,
    sender_email: senderEmail,
    lineItems,
  },
}];

const item = $('Loop Over Line Items').last().json;
const err = $input.first().json;
return [{
  json: {
    ...item,
    stockAction: 'api_error',
    currentStock: null,
    errorReason: 'Shopify API lookup failed/timed out for "' + item.productTitle + '": ' + (err.message || JSON.stringify(err)).slice(0, 250),
  },
}];

const item = $('Loop Over Line Items').last().json;
const res = $input.first().json || {};

let stockAction = 'adjust';
let errorReason = '';
let currentStock = null;
let inventoryItemId = null;
let locationId = null;
let locationName = '';
let mutationBody = null;

if (!item.variantId) {
  stockAction = 'api_error';
  errorReason = 'Line item "' + item.productTitle + '" has no Shopify variantId (custom/manual item).';
} else if (res.errors && res.errors.length) {
  stockAction = 'api_error';
  errorReason = 'Shopify GraphQL error: ' + JSON.stringify(res.errors);
} else {
  const variant = res.data && res.data.productVariant;
  const inv = variant && variant.inventoryItem;
  if (!variant || !inv) {
    stockAction = 'api_error';
    errorReason = 'Variant ' + item.variantId + ' not found or has no inventoryItem in Shopify.';
  } else if (!inv.tracked) {
    stockAction = 'not_tracked';
    errorReason = 'Inventory tracking is disabled for "' + item.productTitle + '" (variant ' + item.variantId + ').';
  } else {
    const levels = (inv.inventoryLevels && inv.inventoryLevels.nodes) || [];
    const primaryLevel = levels[0];
    if (!primaryLevel) {
      stockAction = 'api_error';
      errorReason = 'No inventory location level found for "' + item.productTitle + '".';
    } else {
      inventoryItemId = inv.id;
      locationId = primaryLevel.location && primaryLevel.location.id;
      locationName = (primaryLevel.location && primaryLevel.location.name) || 'Default';
      const availObj = (primaryLevel.quantities || []).find((q) => q.name === 'available');
      currentStock = availObj ? Number(availObj.quantity) : 0;

      if (currentStock <= 0 || (currentStock - item.quantity) < 0) {
        stockAction = 'out_of_stock';
        errorReason = 'Insufficient stock for "' + item.productTitle + '" (Available: ' + currentStock + ', Ordered: ' + item.quantity + '). Negative stock prevented.';
      } else {
        mutationBody = {
          query: 'mutation inventoryAdjustQuantities($input: InventoryAdjustQuantitiesInput!, $idempotentKey: String!) { inventoryAdjustQuantities(input: $input) @idempotent(key: $idempotentKey) { inventoryAdjustmentGroup { reason changes { name delta quantityAfterChange } } userErrors { field message } } }',
          variables: {
            idempotentKey: String(item.shopifyOrderId) + '-' + String(item.lineItemId),
            input: {
              reason: 'correction',
              name: 'available',
              changes: [
                {
                  delta: -item.quantity,
                  changeFromQuantity: currentStock,
                  inventoryItemId,
                  locationId,
                },
              ],
            },
          },
        };
      }
    }
  }
}

return [{
  json: {
    ...item,
    stockAction,
    errorReason,
    currentStock,
    expectedRemaining: currentStock !== null ? (currentStock - item.quantity) : null,
    inventoryItemId,
    locationId,
    locationName,
    mutationBody,
  },
}];

const item = $('Evaluate Stock & Build Mutation').last().json;
const err = $input.first().json;
return [{
  json: {
    ...item,
    errorReason: 'Shopify inventory update failed/timed out for "' + item.productTitle + '": ' + (err.message || JSON.stringify(err)).slice(0, 250),
  },
}];

const ctx = $('Evaluate Stock & Build Mutation').last().json;
const res = $input.first().json || {};

const adj = res.data && res.data.inventoryAdjustQuantities;
const userErrors = (adj && adj.userErrors) || [];
if ((res.errors && res.errors.length) || userErrors.length) {
  throw new Error('Shopify inventory adjustment failed for ' + ctx.productTitle + ': ' + JSON.stringify(userErrors.length ? userErrors : res.errors));
}

const changes = (adj && adj.inventoryAdjustmentGroup && adj.inventoryAdjustmentGroup.changes) || [];
const availChange = changes.find((c) => c.name === 'available') || changes[0];
const remainingStock = availChange && availChange.quantityAfterChange !== undefined
  ? Number(availChange.quantityAfterChange)
  : Number(ctx.expectedRemaining);

const isLowStock = remainingStock < Number(ctx.low_stock_threshold);

return [{
  json: {
    ...ctx,
    processedStatus: 'updated',
    remainingStock,
    isLowStock,
  },
}];

const item = $('Parse Inventory Result').last().json;
const err = $input.first().json;
return [{
  json: {
    ...item,
    sheetsError: (err.message || JSON.stringify(err)).slice(0, 250),
  },
}];

