let item;
try {
  item = $('Evaluate Stock & Build Mutation').last().json;
} catch (e) {
  item = $('Loop Over Line Items').last().json;
}
const errInput = $input.first().json || {};
const errMsg = item.errorReason || errInput.errorReason || (errInput.error && errInput.error.message) || errInput.message || 'Shopify inventory lookup/update failed';

return [{
  json: {
    orderId: item.orderId,
    shopifyOrderId: item.shopifyOrderId,
    customerName: item.customerName,
    customerEmail: item.customerEmail,
    hasValidEmail: item.hasValidEmail,
    customerDisplay: item.customerDisplay,
    currency: item.currency,
    totalAmount: item.totalAmount,
    processedAt: item.processedAt,
    low_stock_threshold: item.low_stock_threshold,
    store_name: item.store_name,
    owner_telegram_chat_id: item.owner_telegram_chat_id,
    sender_email: item.sender_email,
    productTitle: item.productTitle,
    productDisplay: item.productDisplay,
    sku: item.sku,
    quantity: item.quantity,
    unitPrice: item.unitPrice,
    lineRevenue: item.lineRevenue,
    remainingStock: item.currentStock !== undefined && item.currentStock !== null ? item.currentStock : 'N/A',
    isLowStock: false,
    processedStatus: 'failed',
    errorReason: errMsg,
  },
}];

const summary = $('Build Order Summary & Email').first().json;
const err = $input.first().json;
return [{
  json: {
    owner_telegram_chat_id: summary.owner_telegram_chat_id,
    orderId: summary.orderId,
    customerEmail: summary.customerEmail,
    errorMsg: (err.message || JSON.stringify(err)).slice(0, 250),
  },
}];
